    @field_validator("mobile")
    @classmethod
    def validate_phone(cls, v: str) -> str:
        v = v.strip()

        if not v.isdigit():
            raise ValueError("⚠️ 電話號碼只能包含數字")

        if len(v) != 8:
            raise ValueError("⚠️ 電話號碼必須正正係8位數字")

        return v

    @classmethod
    async def add_supplier_function(cls, 
                                    supplier_name: str, 
                                    mobile: str, 
                                    supplier_type: str,
                                    supplier_locations_request: Optional[List[SupplierLocation]] = None
                                    ):

        existing_supplier = await cls.find_one(cls.company_name == supplier_name, 
                                                   cls.deleted_at == None)

        if existing_supplier:
            raise ValueError(f"⚠️ 呢個名為{supplier_name}嘅供應商已添加。")

        if supplier_locations_request:
            if len(supplier_locations_request) > 2:
                raise ValueError("⚠️ 最多只可以有兩個供應商地址（碼頭 / 倉庫）。")

            location_names = [loc.location_name for loc in supplier_locations_request]
            if len(set(location_names)) != len(location_names):
                raise ValueError("⚠️ 供應商地址類型（碼頭 / 倉庫）不能重複。")

            validated_locations = [SupplierLocation(**loc.model_dump()) for loc in supplier_locations_request]

        try:
            new_supplier = cls(
                company_name=supplier_name,
                supplier_type=supplier_type,
                mobile=mobile,
                supplier_locations=validated_locations,
                created_at=datetime.now(),
                )
            await new_supplier.insert()

            result = {
                "success": True,
                "message": f"✅ 供應商「{supplier_name}」添加成功。",
                "supplier": {
                    "supplier_id": str(new_supplier.id),
                    "company_name": new_supplier.company_name,
                    "supplier_type": new_supplier.supplier_type,
                    "mobile": new_supplier.mobile,
                    "supplier_locations": [
                    loc.model_dump() for loc in new_supplier.supplier_locations
                ] if new_supplier.supplier_locations else None
            }
        }
            return result

        except Exception as e:
            return {"success": False, "message": str(e)}



    @classmethod
    async def add_supplier_address_function(cls, 
                                            supplier_name: str, 
                                            locations: List[SupplierLocation]):
        try:
            existing_supplier = await cls.find_one(cls.company_name == supplier_name, 
                                                   cls.deleted_at == None)

            if not existing_supplier:
                raise ValueError(f"⚠️ 呢個名為{supplier_name}嘅供應商不存在。")

            for location in locations:
                new_location = SupplierLocation(
                    location_name=location.location_name,
                    district=location.district,
                    street=location.street,
                    building=location.building
                )

            if existing_supplier.supplier_locations:
                existing_supplier.supplier_locations.append(new_location)
            else:
                existing_supplier.supplier_locations = [new_location]

            await existing_supplier.save()

            response = (
                f"✅ 供應商「{supplier_name}」嘅地址添加成功：\n"
                f"📍 地點名稱：{location.location_name.value}\n"
                f"🏙️ 地區：{location.district}\n"
                f"🛣️ 街道：{location.street}\n"
                f"🏢 大廈：{location.building or '（無提供）'}")

            return response

        except Exception as e:
            response = str(e)
            return response


    @classmethod
    async def update_supplier_function(
        cls, 
        supplier_id: str,
        company_name: Optional[str] = None,
        supplier_type: Optional[str] = None,
        mobile: Optional[str] = None,
        supplier_locations: Optional[List[SupplierLocation]] = None
        ) -> dict:

        try:
            existing_supplier = await cls.get(supplier_id)
            if not existing_supplier or existing_supplier.deleted_at is not None:
                message = f"⚠️ 沒搵到 ID 為 {supplier_id} 嘅供應商。"
                return {
                    "status": "error",
                    "message": message
                    }

            updates = []

            if company_name and company_name != existing_supplier.company_name:
                updates.append(f"公司名稱由「{existing_supplier.company_name}」改為「{company_name}」。")
                existing_supplier.company_name = company_name

            if supplier_type and supplier_type != existing_supplier.supplier_type:
                updates.append(f"供應商類型由「{existing_supplier.supplier_type}」改為「{supplier_type}」。")
                existing_supplier.supplier_type = supplier_type

            if mobile and mobile != existing_supplier.mobile:
                updates.append(f"電話號碼由「{existing_supplier.mobile}」改為「{mobile}」。")
                existing_supplier.mobile = mobile

            if supplier_locations:
                # Merge with existing
                combined_locations = {
                    loc.location_name: loc
                    for loc in (existing_supplier.supplier_locations or [])
                    }

                for loc in supplier_locations:
                    if loc.location_name not in {"碼頭", "倉庫"}:
                        detail=f"⚠️ 位置名必須係「碼頭」或者「倉庫」，而呢個係 {loc.location_name}。"
                        return {
                            "status": "error",
                            "message": detail}

                    combined_locations[loc.location_name] = loc  # Overwrite if exists

                if len(combined_locations) > 2:
                    return {
                    "status": "error",
                    "message": "⚠️ 最多只可以有兩個供應商地址（碼頭 / 倉庫）。"
                }

                # Rule 3: Ensure no duplicate keys already handled via dict keys
                existing_supplier.supplier_locations = list(combined_locations.values())
                updates.append("供應商地址已更新。")

            if not updates:
                return {
                "status": "error",
                "message": "⚠️ 冇任何變更項目，無需更新。"
            }

            await existing_supplier.save()
            return {
            "status": "success",
            "message": f"✅ 供應商已更新：\n" + "\n".join(updates)
        }

        except Exception as e:
            return {
            "status": "error",
            "message": f"⚠️ 更新時發生錯誤：{str(e)}"
        }




    @classmethod
    async def delete_supplier_function(
        cls,
        supplier_id: str):
        try:
            existing_supplier = await cls.get(supplier_id)
            if not existing_supplier or existing_supplier.deleted_at is not None:
                message = f"⚠️ 沒搵到 ID 為 {supplier_id} 嘅供應商。"
                return {
                    "status": "error",
                    "message": message
                    }

            supplier_name = existing_supplier.company_name
            existing_supplier.deleted_at = datetime.now()
            await existing_supplier.save()
            response = f"✅ 供應商「{supplier_name}」已經成功🗑️刪除啦～。"

            return response

        except Exception as e:
            response = str(e)
            return response


    @classmethod
    async def read_all_supplier_function(cls):
        try:
            all_suppliers_info = await cls.find(cls.deleted_at == None).to_list()

            supplier_data = [
                {
                    "supplier_id": str(supplier.id),
