        all_supplier_names = await cls.find(cls.deleted_at == None).to_list()

        supplier_data = [
            {
                "supplier_name": supplier.company_name,
                "supplier_id": str(supplier.id)
            }
            for supplier in all_supplier_names
        ]

        return supplier_data

