                ),
                serialization=core_schema.plain_serializer_function_ser_schema(
                    lambda instance: cls.to_dict(instance),
                    return_schema=core_schema.dict_schema(),
                    when_used="json-unless-none",
                ),
            )

    else:

        @classmethod
        def __get_validators__(cls):
