    """

    @classmethod
    def _validate(cls, v):
        if isinstance(v, bytes):
            v = v.decode("utf-8")
        try:
            return PydanticObjectId(v)
        except (InvalidId, TypeError):
            raise ValueError("Id must be of type PydanticObjectId")

    if IS_PYDANTIC_V2:

        @classmethod
        def __get_pydantic_core_schema__(
            cls, source_type: Type[Any], handler: GetCoreSchemaHandler
        ) -> CoreSchema:
            definition = core_schema.definition_reference_schema(
                "PydanticObjectId"
            )  # used for deduplication

            return core_schema.definitions_schema(
                definition,
                [
                    core_schema.json_or_python_schema(
                        python_schema=core_schema.no_info_plain_validator_function(
                            cls._validate
                        ),
                        json_schema=core_schema.no_info_after_validator_function(
                            cls._validate,
                            core_schema.str_schema(
                                pattern="^[0-9a-f]{24}$",
                                min_length=24,
                                max_length=24,
                            ),
                        ),
                        serialization=core_schema.plain_serializer_function_ser_schema(
                            lambda instance: str(instance), when_used="json"
                        ),
                        ref=definition["schema_ref"],
                    )
                ],
            )

        @classmethod
        def __get_pydantic_json_schema__(
            cls,
            schema: core_schema.CoreSchema,
            handler: GetJsonSchemaHandler,  # type: ignore
        ) -> JsonSchemaValue:
            """
            Results such schema:
            ```json
            {
              "components": {
                "schemas": {
                  "Item": {
                    "properties": {
                      "id": {
                        "$ref": "#/components/schemas/PydanticObjectId"
                      }
                    },
                    "type": "object",
                    "title": "Item"
                  },
                  "PydanticObjectId": {
                    "type": "string",
                    "maxLength": 24,
                    "minLength": 24,
                    "pattern": "^[0-9a-f]{24}$",
                    "example": "5eb7cf5a86d9755df3a6c593"
                  }
                }
              }
            }
            ```
            """

            json_schema = handler(schema)
            schema_to_update = handler.resolve_ref_schema(json_schema)
            schema_to_update.update(example="5eb7cf5a86d9755df3a6c593")
            return json_schema

    else:

        @classmethod
        def __get_validators__(cls):
            yield cls._validate

        @classmethod
        def __modify_schema__(cls, field_schema: Dict[str, Any]):
            field_schema.update(
                type="string",
                example="5eb7cf5a86d9755df3a6c593",
            )


