@simstack_model
class DataSetMetadata(EmbeddedModel):
    field_name: str = Field(unique=True)
    data: Dict[str, Union[str, int, float, bool, datetime]] = Field(
        default_factory=dict
    )
    is_validated: bool = False
    structure: Dict[str, Dict[str, str]] = Field(default_factory=dict)

    def get_json_schema(self):
        return _get_json_schema(self.data)

    async def validate_dict(self, new_structure: Dict[str, Dict[str, str]], dataset_tuple: bool = False) -> bool:
        """
        Asynchronously validates and updates the structure of a dataset metadata template based on a provided dictionary.

        This function ensures that the structure of the provided `new_structure` aligns
        with the pre-existing metadata template stored in the database. If the metadata
        template does not exist, it initializes a new one. Schema properties and section
        contents are rigorously compared for consistency, and any mismatches result in
        an exception being raised. The function also handles updates to the template when
        new sections or keys are introduced.

        Parameters:
            new_structure (Dict[str, Dict[str, str]]): A dictionary describing the sections
                and their respective key-type mappings for the new dataset structure.
            dataset_tuple (bool, optional): A flag indicating whether the provided structure
                should be treated as a tuple. Defaults to False.

        Returns:
            bool: True if the structure is successfully validated or updated.

        Raises:
            ValueError: If there is a mismatch between the existing and provided schema
                properties or section content.
        """
        from simstack.core.context import context
        reference_metadata = await context.db.find_one(
            DataSetMetadataTemplate,
            DataSetMetadataTemplate.dataset_type == self.field_name,
        )
        # remove empty sections without mutating the dict during iteration
        new_structure = {
            key: value for key, value in new_structure.items() if value
        }

        if reference_metadata is None:
            metadata_template = DataSetMetadataTemplate(
                dataset_type=self.field_name,
                model_json=_get_json_schema(self.data),
                structure=new_structure,
            )
            await context.db.save(metadata_template)
            self.structure = new_structure
            return True  # first model of this type

        new_data_json = _get_json_schema(self.data)

        # Compare schemas element by element
        # this section compares whether the data in the metadata is the same
        ref_props = reference_metadata.model_json.get("properties", {})
        new_props = new_data_json.get("properties", {})

        # Check if property keys match
        if set(ref_props.keys()) != set(new_props.keys()):
            raise ValueError(
                f"Data schema properties mismatch. Reference keys: {set(ref_props.keys())}, Current keys: {set(new_props.keys())}"
            )

        # Check each property type, allowing string format differences
        for key in ref_props.keys():
            ref_prop = ref_props[key]
            new_prop = new_props[key]

            ref_type = ref_prop.get("type")
            new_type = new_prop.get("type")

            if ref_type != new_type:
                raise ValueError(
                    f"Property '{key}' type mismatch. Reference: {ref_type}, Current: {new_type}"
                )

            # For string types, allow the format field to differ or be missing
            if ref_type == "string":
                # Compare all fields except 'format'
                ref_without_format = {k: v for k, v in ref_prop.items() if k != "format"}
                new_without_format = {k: v for k, v in new_prop.items() if k != "format"}
                if ref_without_format != new_without_format:
                    raise ValueError(
                        f"Property '{key}' schema mismatch (excluding format). Reference: {ref_without_format}, Current: {new_without_format}"
                    )
            else:
                # For non-string types, require exact match
                if ref_prop != new_prop:
                    raise ValueError(
                        f"Property '{key}' schema mismatch. Reference: {ref_prop}, Current: {new_prop}"
                    )

        # Check if model types in existing sections match, and add new keys
        save_template = False
        updated_structure = reference_metadata.structure.copy()

        for section_name, new_section_content in new_structure.items():
            if section_name in updated_structure:
                ref_section_content = updated_structure[section_name]
                # Check if all elements in new_section_content match ref_section_content exactly

                if dataset_tuple: # for tuples the sections must be exactly the same
                    if ref_section_content != new_section_content:
                        raise ValueError(
                            f"Section '{section_name}' content mismatch. Reference: {ref_section_content}, Current: {new_section_content}"
                        )
                    continue
                else:
                    ref_keys = set(ref_section_content.keys())
                    new_keys = set(new_section_content.keys())

                    extra_keys = new_keys - ref_keys

                    # Check for type mismatches in common keys
                    common_keys = ref_keys.intersection(new_keys)
                    for key in common_keys:
                        if ref_section_content[key] != new_section_content[key]:
                            error_msg = f"MetaData Validation failed: Section '{section_name}' has different value for key '{key}'.\n"
                            error_msg += f"Reference: {ref_section_content[key]}, Current: {new_section_content[key]}\n"
                            error_msg += f"Reference keys: {ref_keys}\n"
                            error_msg += f"Current keys: {new_keys}"
                            raise ValueError(error_msg)

                    if len(extra_keys) > 0:
                        for key in extra_keys:
                            updated_structure[section_name][key] = new_section_content[key]
                            save_template = True
            else:
                # Completely new section
                updated_structure[section_name] = new_section_content
                save_template = True

        if save_template:
            reference_metadata.structure = updated_structure
            await context.db.save(reference_metadata)
        self.structure = updated_structure
        return True

    @async_helper
    async def freeze(self, new_structure: Dict[str, Dict[str, str]]) -> bool:
        from simstack.core.context import context
        db = context.db
        reference_metadata = await db.find_one(
            DataSetMetadataTemplate,
            DataSetMetadataTemplate.dataset_type == self.field_name,
        )
        if not reference_metadata:
            raise ValueError("Metadata does not exist")
        if self.structure != reference_metadata.structure:
            raise ValueError("Metadata structure has changed in the database")
        if self.structure == {}:
            self.structure = new_structure
            reference_metadata.structure = new_structure
            await db.save(reference_metadata)
        # some structure exists already
        return new_structure == self.structure

    @property
    def initialized(self) -> bool:
        """Check if the model has been fully constructed."""
        # A simple heuristic: if we have an ID or if type is set, we're initialized
        return hasattr(self, "dataset_type") and self.field_name is not None

    # Dict-like behavior methods
    def __getitem__(self, key: str):
        """Get item from data dict."""
        return self.data[key]

    def __setitem__(self, key: str, value: Union[str, int, float, bool, datetime]):
        """Set item in data dict with validation."""
        # Validate value type
        if not isinstance(value, (str, int, float, bool, datetime)):
            raise TypeError(
                f"Value must be str, int, float, bool, or datetime, got {type(value).__name__}"
            )

        # Only check for structural changes after initialization
        if self.initialized and key not in self.data:
            raise KeyError(
                f"Cannot add new key '{key}' after initialization. Existing keys: {list(self.data.keys())}"
            )

        # Only check for type changes after initialization
        if self.initialized and key in self.data:
            existing_value = self.data[key]
            if type(existing_value) != type(value):
                raise TypeError(
                    f"Cannot change type of key '{key}' from {type(existing_value).__name__} "
                    f"to {type(value).__name__}"
                )

        self.data[key] = value

    def __delitem__(self, key: str):
        """Delete item from data dict."""
        if self.initialized:
            raise KeyError(f"Cannot delete key '{key}' after initialization")
        del self.data[key]

    def __contains__(self, key: str) -> bool:
        """Check if key exists in data dict."""
        return key in self.data

    def __iter__(self):
        """Iterate over keys in data dict."""
        return iter(self.data)

    def __len__(self) -> int:
        """Get number of items in data dict."""
        return len(self.data)

    def keys(self):
        """Get keys from data dict."""
        return self.data.keys()

    def values(self):
        """Get values from data dict."""
        return self.data.values()

    def items(self):
        """Get items from data dict."""
        return self.data.items()

    def get(self, key: str, default=None):
        """Get item from data dict with default."""
        return self.data.get(key, default)

    def pop(self, key: str, *args):
        """Pop item from data dict."""
        if self.initialized:
            raise KeyError(f"Cannot pop key '{key}' after initialization")
        return self.data.pop(key, *args)

    def popitem(self):
        """Pop item from data dict."""
        if self.initialized:
            raise KeyError("Cannot pop items after initialization")
        return self.data.popitem()

    def clear(self):
        """Clear data dict."""
        if self.initialized:
            raise RuntimeError("Cannot clear data after initialization")
        self.data.clear()

    def update(self, *args, **kwargs):
        """Update data dict with validation."""
        # Handle different update signatures
        if args:
            other = args[0]
            if hasattr(other, "items"):
                items_to_update = other.items()
            else:
                items_to_update = other
        else:
            items_to_update = []

        # Combine with kwargs
        all_items = list(items_to_update) + list(kwargs.items())

        # Validate all items before updating
        for key, value in all_items:
            # Type validation (always required)
            if not isinstance(value, (str, int, float, bool, datetime)):
                raise TypeError(
                    f"Value for key '{key}' must be str, int, float, bool, or datetime, got {type(value).__name__}"
                )

            # Structural validation (only after initialization)
            if self.initialized:
                if key not in self.data:
                    raise KeyError(f"Cannot add new key '{key}' after initialization")

                existing_value = self.data[key]
                if type(existing_value) != type(value):
                    raise TypeError(
                        f"Cannot change type of key '{key}' from {type(existing_value).__name__} "
                        f"to {type(value).__name__}"
                    )

        # If all validations pass, update the data
        for key, value in all_items:
            self.data[key] = value

    def setdefault(self, key: str, default=None):
        """Set default value for key if not exists."""
        if key not in self.data:
            if self.initialized:
                raise KeyError(f"Cannot add new key '{key}' after initialization")

            if default is not None and not isinstance(
                default, (str, int, float, bool, datetime)
            ):
                raise TypeError(
                    f"Default value must be str, int, float, bool, or datetime, got {type(default).__name__}"
                )

            self.data[key] = default

        return self.data[key]

    # Additional utility methods (no initialization checks needed)
    def copy_data(self) -> Dict[str, Union[str, int, float, bool, datetime]]:
        """Return a copy of the data dict."""
        return self.data.copy()

    def is_type_compatible(self, key: str, value) -> bool:
        """Check if a value is type-compatible with existing key."""
        if key not in self.data:
            return isinstance(value, (str, int, float, bool, datetime))
        return type(self.data[key]) == type(value)

    def get_key_type(self, key: str) -> type:
        """Get the type of a specific key."""
        if key not in self.data:
            raise KeyError(f"Key '{key}' not found")
        return type(self.data[key])

    def get_schema_for_key(self, key: str) -> dict:
        """Get JSON schema for a specific key."""
        if key not in self.data:
            raise KeyError(f"Key '{key}' not found")

        value = self.data[key]
        if isinstance(value, str):
            return {"type": "string"}
        elif isinstance(value, bool):
            return {"type": "boolean"}
        elif isinstance(value, int):
            return {"type": "integer"}
        elif isinstance(value, float):
            return {"type": "number"}
        elif isinstance(value, datetime):
            return {"type": "string", "format": "date-time"}
        else:
            return {"type": "string"}

import uuid
from typing import Dict, Iterator, Union, Tuple, KeysView, ValuesView, ItemsView, List, Optional, Any
from odmantic import Model, ObjectId, EmbeddedModel, Field, Reference
from simstack.core.asnyc_helper import async_helper
from simstack.models import simstack_model
from simstack.models.dataset_metadata import DataSetMetadata
from simstack.util.make_table import make_column_defs_instance
from simstack.util.make_table import make_table_entries_helper


@simstack_model
class DataSetSection(EmbeddedModel):
    """
    Represents a section of a dataset containing dictionaries of models.

    A DataSetSection is a list of dictionaries where for each key, the values are of the same model type.

    :ivar model_types: Dictionary mapping keys to model class names.
    :type model_types: Dict[str, str]
    :ivar data: Dictionary mapping names to dictionaries mapping keys to ObjectIds.
    :type data: Dict[str, Dict[str, ObjectId]]
    """

    model_types: Dict[str, str] = Field(default_factory=dict)

    data: Dict[str, Dict[str, ObjectId]] = Field(default_factory=dict)

    column_defs: List[Dict] = Field(default_factory=list)
    table_entries: List[List[Dict]] = Field(default_factory=list)

    model_config = {"extra": "forbid"}

    def _set_cache(self, cache: Dict[str, Dict[str, Model]]):
        object.__getattribute__(self, "__dict__")["_cache"] = cache
        return cache

    def _get_cache(self) -> Dict[str, Dict[str, Model]]:
        self_dict = object.__getattribute__(self, "__dict__")
        cache = self_dict.get("_cache", None)
        if cache is None:
            cache = {}
            cache = self._set_cache(cache)
        return cache

    def add_row(self, item: Dict[str, Optional[Model]], name: Optional[str] = None) -> None:
        """
        Add a dictionary of models to this section.

        :param item: Dictionary of model instances to add.
        :param name: Optional name for the item. If None, a UUID will be generated.
        :raises ValueError: If the model types don't match the section's expected types.
        :raises TypeError: If a non-None item value is not a Model instance.
        """

        if name is None:
            name = str(uuid.uuid4())

        cache = self._get_cache()
        if name in cache:
            raise ValueError(f"Item with name '{name}' already exists in section")

        if not isinstance(item, dict):
            raise TypeError("Item must be a dictionary")

        # Type check: raise TypeError if an item which is not None is not a Model
        for key, value in item.items():
            if value is not None and not isinstance(value, Model):
                raise TypeError(
                    f"Item with key '{key}' is not a Model instance: {type(value).__name__}"
                )

        filtered_item = {k: v for k, v in item.items() if v is not None}

        current_item_types = {k: v.__class__.__name__ for k, v in filtered_item.items()}

        # If this is the first item, we can partially or fully initialize model_types
        # However, subsequent items might have new keys.
        # The requirement says: "all items with the same key must be the same Model type"

        for key, model_name in current_item_types.items():
            if key in self.model_types:
                if self.model_types[key] != model_name:
                    raise ValueError(
                        f"Model type for key '{key}' is {model_name}, but expected {self.model_types[key]}"
                    )
            else:
                self.model_types[key] = model_name

        # Save all models to cache
        cached_items = {}
        for key, model in item.items():
            if model is None:
                continue
            cached_items[key] = model

        cache[name] = cached_items

    async def make_column_defs(self):
        """
        Generate ag-grid column definitions for all model types in this section.
        """

        from simstack.util.importer import import_class_by_name
        from simstack.core.context import context
        engine = context.db
        column_defs = []
        cache = self._get_cache()
        if not cache:
            return column_defs

        # Use model_types to determine columns. 
        for key, model_type in self.model_types.items():
            model_instance = None
            for row in cache.values():
                if key in row:
                    model_instance = row[key]
                    break

            if model_instance is None:
                continue

            model_columns = make_column_defs_instance(model_instance)
            column_defs.extend(model_columns)

        return column_defs

    async def make_table_entries(self):
        all_data = []
        cache = self._get_cache()
        for row in cache.values():
            row_data = []
            for key, model_type in self.model_types.items():
                model_instance = row.get(key)
                model_data = make_table_entries_helper(model_instance)
                row_data.append(model_data)
            all_data.append(row_data)
        return all_data


    async def save(self, db):
        """
        Save all models in the cache to the database and update data.
        """
        cache = self._get_cache()
        for row_name, row_models in cache.items():
            for model_key, model in row_models.items():
                if model is not None:
                    await db.save_unchecked(model)

        # Sync cache to data before saving
        self.data = {
            name: {k: v.id for k, v in row.items()}
            for name, row in cache.items()
        }

        self.column_defs = await self.make_column_defs()
        self.table_entries = await self.make_table_entries()

    def get_item(self, name: str) -> Dict[str, Model]:
        cache = self._get_cache()
        if name not in cache:
            raise KeyError(f"Item with name '{name}' not found")
        return cache[name]

    async def db_find_postprocess(self, db: "Database"):
        await self.load_to_cache(db)

    async def load_to_cache(self, db: "Database") -> None:
        """
        Load all items from the database into the cache assuming that data is already loaded.
        """
        from simstack.core.context import context
        if db is None:
            db = context.db
        cache = self._get_cache()
        for name, row in self.data.items():
            cached_row = {}
            for key, model_id in row.items():
                model_type = self.model_types[key]
                from simstack.util.importer import import_class_by_name
                model_class = await import_class_by_name(model_type, db)
                model_instance = await db.find_one(model_class, model_class.id == model_id)
                if model_instance is None:
                    raise ValueError(f"Model with id {model_id} of type {model_type} not found")
                cached_row[key] = model_instance

            # Update cache
            cache[name] = cached_row
        self._set_cache(cache)

    def __len__(self) -> int:
        return len(self._get_cache())

    def __iter__(self):
        return iter(self._get_cache().items())

    def __getitem__(self, name: str) -> Dict[str, Model]:
        cache = self._get_cache()
        if name in cache:
            return cache[name]

        raise KeyError(f"Item with name '{name}' not found")

    def __setitem__(self, name: str, value: Dict[str, Optional[Model]]) -> None:
        cache = self._get_cache()
        if name in cache:
             self.pop(name, None)

        self.add_row(value, name=name)

    def __delitem__(self, name: str) -> None:
        cache = self._get_cache()
        if name not in cache:
            raise KeyError(f"Item with name '{name}' not found")
        del cache[name]

    def __contains__(self, name: str) -> bool:
        return name in self._get_cache()

    def get(self, name: str, default: Any = None) -> Any:
        try:
            return self[name]
        except KeyError:
            return default

    def keys(self) -> KeysView[str]:
        return self._get_cache().keys()

    def values(self) -> ValuesView[Dict[str, Model]]:
        return self._get_cache().values()

    def items(self) -> ItemsView[str, Dict[str, Model]]:
        return self._get_cache().items()

    def clear(self) -> None:
        self._set_cache({})

    def pop(self, name: str, default: Any = ...) -> Any:
        cache = self._get_cache()
        if name not in cache:
            if default is ...:
                raise KeyError(f"Item with name '{name}' not found")
            return default

        return cache.pop(name)

    def popitem(self) -> Tuple[str, Dict[str, Model]]:
        cache = self._get_cache()
        if not cache:
            raise KeyError("popitem(): dictionary is empty")
        return cache.popitem()

    def update(self, other: Union[Dict[str, Dict[str, Optional[Model]]], "DataSetSection"]) -> None:
        if isinstance(other, DataSetSection):
            other_cache = other._get_cache()
            for name, row in other_cache.items():
                self[name] = row
        else:
            for name, row in other.items():
                self[name] = row

    def setdefault(self, name: str, default: Dict[str, Optional[Model]] = None) -> Dict[str, Model]:
        cache = self._get_cache()
        if name not in cache:
            self[name] = default
        return self[name]

    def __repr__(self) -> str:
        return f"DataSetSection(keys={list(self.model_types.keys())}, length={len(self)})"


@simstack_model
class DataSet(Model):
    field_name: str = Field(default="dataset")
    metadata: DataSetMetadata
    sections: Dict[str, DataSetSection] = Field(default_factory=dict)

    model_config = {"extra": "forbid"}

    @property
    def dataset_type(self) -> str:
        return self.metadata.dataset_type

    async def save(self, db):
        structure = self.collect_structure()
        # metadata.validate_dict currently expects Dict[str, List[str]]
        # We might need to adjust it or pass something compatible.
        # For now, let's just pass the keys of model_types as a list.
        # Wait, DataSetTuple passes List[str] which are the model names in the tuple.
        # For DataSet, maybe it should be the model names too, but we lose the keys.
        # Let's see how validate_dict uses it.
        ok = await self.metadata.validate_dict(structure)
        if not ok:
            raise ValueError("Metadata validation failed")

        for key, section in self.sections.items():
            await section.save(db)

        await db.save_unchecked(self)

    def collect_structure(self) -> Dict[str, Dict[str, str]]:
        return {
            section_name: section.model_types
            for section_name, section in self.sections.items()
            if section.data or len(section) > 0
        }

    def __getitem__(self, key: str) -> DataSetSection:
        if key not in self.sections:
            self.sections[key] = DataSetSection()
        return self.sections[key]

    def __setitem__(self, key: str, value: DataSetSection) -> None:
        if key in self.sections:
            raise KeyError(f"Section {key} already exists in dataset")
        self.sections[key] = value

    def __delitem__(self, key: str) -> None:
        del self.sections[key]

    def __len__(self) -> int:
        return len(self.sections)

    def __iter__(self) -> Iterator[str]:
        return iter(self.sections)

    def __contains__(self, key: str) -> bool:
        return key in self.sections

    def keys(self) -> KeysView[str]:
        return self.sections.keys()

    def values(self) -> ValuesView[DataSetSection]:
        return self.sections.values()

    def items(self) -> ItemsView[str, DataSetSection]:
        return self.sections.items()

    def get(self, key: str, default: DataSetSection = None) -> DataSetSection:
        return self.sections.get(key, default)

    def pop(self, key: str, default=None) -> DataSetSection:
        return self.sections.pop(key, default)

    def clear(self):
        self.sections.clear()

    def update(
        self, other: Union[Dict[str, DataSetSection], "DataSet"] = None, **kwargs
    ) -> None:
        if other is not None:
            if hasattr(other, "sections"):
                self.sections.update(other.sections)
            else:
                self.sections.update(other)
        self.sections.update(kwargs)

    def setdefault(self, key: str, default: DataSetSection = None) -> DataSetSection:
        return self.sections.setdefault(key, default)

    @classmethod
    def ui_schema(cls) -> dict:
        return {
            "ui:field": "DataSetField",
            "metadata": {"ui:widget": "hidden"},
            "sections": {"ui:widget": "hidden"},
        }


class DataSetSelectionField(EmbeddedModel):
    section_name: str = Field(default="default")
    indices: List[int] = Field(default_factory=list)

@simstack_model
class DataSetSelection(Model):
    field_name: str = Field(default="dataset_selection")
    dataset_id: ObjectId
    dataset_selection_fields: List[DataSetSelectionField] = Field(default_factory=list)

    async def get_dataset(self):
        from simstack.core.context import context
        return await context.db.find_one(DataSet, DataSet.id == self.dataset_id)

    @async_helper
    async def get_selected_elements(self, section_name: str = None) -> List[Tuple[Model, ...]]:
        """
        Retrieve all selected model groups from the dataset.

        :param section_name: Optional section name to filter results. If None, returns all sections.
        :return: List of tuples of model instances for all selected elements
        """
        from simstack.core.context import context
        db = context.db
        dataset = await db.find_one(DataSet, DataSet.id == self.dataset_id)

        if dataset is None:
            raise ValueError(f"Dataset with id {self.dataset_id} not found")

        selected_elements = []
        for selection_field in self.dataset_selection_fields:
            if section_name is not None and selection_field.section_name != section_name:
                continue

            section = dataset.sections.get(selection_field.section_name)
            if section is None:
                raise ValueError(f"Section {selection_field.section_name} not found in dataset")

            for index in selection_field.indices:
                if index >= len(section):
                    raise IndexError(
                        f"Index {index} out of range for section {selection_field.section_name} with {len(section)} elements"
                    )
                model_group = section.get_model_group(index)
                selected_elements.append(model_group)

        return selected_elements

    async def __aiter__(self, section_name: str = None):
        """
        Async iterator over all selected model groups.

        :param section_name: Optional section name to filter results. If None, returns all sections.
        :return: Async iterator yielding tuples of model instances
        """
        from simstack.core.context import context
        db = context.db
        dataset = await db.find_one(DataSet, DataSet.id == self.dataset_id)

        if dataset is None:
            raise ValueError(f"Dataset with id {self.dataset_id} not found")

        for selection_field in self.dataset_selection_fields:
            if section_name is not None and selection_field.section_name != section_name:
                continue

            section = dataset.sections.get(selection_field.section_name)
            if section is None:
                raise ValueError(f"Section {selection_field.section_name} not found in dataset")

            for index in selection_field.indices:
                if index >= len(section):
                    raise IndexError(
                        f"Index {index} out of range for section {selection_field.section_name} with {len(section)} elements"
                    )
                yield section.get_model_group(index)

    @classmethod
    def ui_schema(cls) -> dict:
        return {
            "ui:field": "DataSetSelectionField",
        }

