        Consolidate capabilities list and return resulting dict of
        caps name -> caps value. First appearance of capability
        overrides later ones.

        :return:
        """
        r: dict[str, Any] = {}
        for caps in args:
            for ci in caps:
                cn = ci.capability.name
                if cn in r:
                    continue
                r[cn] = ci.value
        return r

    def clean(self):
        if self.capability:
            self.value = self.capability.clean_value(self.value)


